#include <stdio.h>
#include <math.h>
#include <ctype.h>

int main(void) {
    double x = 81.0;
    printf("root=%.1f power=%.1f\n", sqrt(x), pow(2.0, 3.0));
    printf("floor=%.1f ceil=%.1f round=%.1f\n", floor(-2.7), ceil(-2.7), round(-2.5));
    unsigned char ch = 'a';
    printf("alpha=%d upper=%c\n", isalpha(ch) != 0, toupper(ch));
    return 0;
}
